         <p>This photo is currently available across your synced devices and albums. Deleting it will remove it from your library.</p>

         <div class="meta-list">
           <div class="meta-row">
             <span class="meta-label">File name</span>
             <p>alpine-horizon.jpg</p>
           </div>
           <div class="meta-row">
             <span class="meta-label">Size</span>
             <p>8.4 MB</p>
           </div>
           <div class="meta-row">
             <span class="meta-label">Collection</span>
             <p>Travel photography</p>
           </div>
           <div class="meta-row">
             <span class="meta-label">Uploaded</span>
             <p>April 23, 2026</p>
           </div>
         </div>
       </aside>
     </section>
   </main>

   <div class="modal" id="delete-dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title" aria-describedby="dialog-description" hidden>
     <div class="modal-backdrop" data-close="true"></div>
     <div class="dialog">
       <div class="dialog-icon" aria-hidden="true">!</div>
       <h2 id="dialog-title">Delete this image?</h2>
       <p id="dialog-description">This action removes the image from your library. You can’t undo the deletion once it’s confirmed.</p>
       <div class="dialog-actions">
         <button class="secondary-btn" id="cancel-dialog" type="button">Cancel</button>
         <button class="danger-btn" id="confirm-delete" type="button">Delete</button>
       </div>
     </div>
   </div>

   <p class="sr-only" id="status-message" aria-live="polite"></p>

   <script>
     const modal = document.getElementById("delete-dialog");
     const openButton = document.querySelector(".trigger");
     const cancelButton = document.getElementById("cancel-dialog");
     const confirmButton = document.getElementById("confirm-delete");
     const statusMessage = document.getElementById("status-message");

     function openDialog() {
       modal.hidden = false;
       cancelButton.focus();
     }

     function closeDialog() {
       modal.hidden = true;
       openButton.focus();
     }

     openButton.addEventListener("click", openDialog);
     cancelButton.addEventListener("click", closeDialog);

     confirmButton.addEventListener("click", function () {
       statusMessage.textContent = "Image deleted from your library.";
       closeDialog();
     });

     modal.addEventListener("click", function (event) {
       if (event.target.dataset.close === "true") {
         closeDialog();
       }
     });

     document.addEventListener("keydown", function (event) {
       if (event.key === "Escape" && !modal.hidden) {
         closeDialog();
       }
     });
   </script>
 </body>
 </html>

